unsigned flac_process_audio_data(SF_PRIVATE *psf, unsigned len) {
    unsigned bytes_processed = 0;

    if (!psf || len == 0)
        return 0;

    // Copy already decoded data from the buffer if available
    if (psf->decoder.buffer_pos > 0 && psf->decoder.buffer_pos < psf->decoder.buffer_len) {
        unsigned bytes_to_copy = psf->decoder.buffer_len - psf->decoder.buffer_pos;
        if (bytes_to_copy > len)
            bytes_to_copy = len;

        // Copy decoded data (example logic, adjust as per actual data type)
        memcpy(psf->output_buffer + bytes_processed, psf->decoder.buffer + psf->decoder.buffer_pos, bytes_to_copy);
        bytes_processed += bytes_to_copy;
        psf->decoder.buffer_pos += bytes_to_copy;
        len -= bytes_to_copy;
    }

    while (len > 0 && psf->decoder.state == FLAC_DECODER_RUNNING) {
        // Read and decode more data (placeholder logic for decoding)
        unsigned decoded = decode_audio_data(psf, len);
        if (decoded == 0) {
            // No more data to decode
            psf->decoder.state = FLAC_DECODER_EOF;
            break;
        }

        bytes_processed += decoded;
        len -= decoded;
    }

    if (psf->decoder.state != FLAC_DECODER_RUNNING) {
        // Log error or end of stream
        switch (psf->decoder.state) {
            case FLAC_DECODER_EOF:
                psf_log(psf, "End of stream reached.");
                break;
            case FLAC_DECODER_ERROR:
                psf_log(psf, "Error during decoding.");
                break;
            default:
                psf_log(psf, "Unknown decoder state.");
                break;
        }

        // Nullify the frame pointer
        psf->decoder.current_frame = NULL;
    }

    return bytes_processed;
}

unsigned flac_process_audio_loop(SF_PRIVATE *psf, unsigned len)
{
    unsigned processed = 0;

    if (psf == NULL || len == 0)
        return 0;

    if (psf->flacDecoder.buffer_used > 0) {
        unsigned copy = SF_MIN(len, psf->flacDecoder.buffer_used);
        memcpy(psf->flacDecoder.output, psf->flacDecoder.buffer, copy);
        psf->flacDecoder.buffer_used -= copy;
        memmove(psf->flacDecoder.buffer, psf->flacDecoder.buffer + copy, psf->flacDecoder.buffer_used);
        processed += copy;
        len -= copy;
    }

    while (len > 0 && !psf->flacDecoder.eof) {
        unsigned read = flac_decoder_read(psf, len);
        if (read == 0) {
            if (psf->flacDecoder.state != FLAC__STREAM_DECODER_SEARCHING_FOR_METADATA &&
                psf->flacDecoder.state != FLAC__STREAM_DECODER_READING_METADATA) {
                psf_log_printf(psf, "FLAC decoding error: %s\n", FLAC__StreamDecoderStateString[psf->flacDecoder.state]);
            }
            break;
        }
        processed += read;
        len -= read;
    }

    if (psf->flacDecoder.state != FLAC__STREAM_DECODER_OK) {
        psf_log_printf(psf, "FLAC decoding error: %s\n", FLAC__StreamDecoderStateString[psf->flacDecoder.state]);
    }

    if (psf->flacDecoder.state == FLAC__STREAM_DECODER_END_OF_STREAM || psf->flacDecoder.state != FLAC__STREAM_DECODER_OK) {
        psf->flacDecoder.frame = NULL;
    }

    return processed;
}

unsigned flac_decoder_audio_loop(SF_PRIVATE *psf, unsigned len) {
    unsigned bytes_processed = 0;
    unsigned current_position = 0;
    unsigned remaining_length = len;

    while (remaining_length > 0 && psf->decoder_state != FLAC_DECODER_ERROR) {
        if (psf->decoder_state == FLAC_DECODER_FRAME_DECODED) {
            if (psf->buffer && psf->buffer_size > 0) {
                unsigned bytes_to_copy = psf->buffer_size;
                if (bytes_to_copy > remaining_length)
                    bytes_to_copy = remaining_length;
                // Copy decoded data from buffer
                memcpy(psf->output + bytes_processed, psf->buffer, bytes_to_copy);
                bytes_processed += bytes_to_copy;
                remaining_length -= bytes_to_copy;
                psf->buffer_size = 0;
            }
        }

        if (psf->decoder_state == FLAC_DECODER_NEED_MORE_DATA) {
            unsigned bytes_read = read_audio_data(psf, current_position, remaining_length);
            if (bytes_read == 0) {
                psf->decoder_state = FLAC_DECODER_EOF;
            }
            current_position += bytes_read;
            bytes_processed += bytes_read;
            remaining_length -= bytes_read;
        }

        if (psf->decoder_state == FLAC_DECODER_EOF || psf->decoder_state == FLAC_DECODER_ERROR) {
            if (psf->decoder_state == FLAC_DECODER_ERROR)
                log_flac_error(psf->error_code);
            psf->frame = NULL;
            break;
        }
    }

    return bytes_processed;
}

unsigned flac_process_audio_data(SF_PRIVATE *psf, unsigned len) {
    unsigned bytes_processed = 0;
    unsigned position = 0;
    unsigned read_len = 0;

    if (psf == NULL || len == 0)
        return 0;

    if (psf->flac_decoder == NULL)
        return 0;

    if (psf->flac_decoder->state != FLAC__DECODER_OK) {
        psf_log_printf(psf, "FLAC decoder is not in a valid state: %s\n", FLAC__StreamDecoderStateString[psf->flac_decoder->state]);
        return 0;
    }

    /* Copy any already decoded data from the buffer */
    if (psf->flac_decoder->output_ptr && psf->flac_decoder->output_bytes_remaining > 0) {
        read_len = SF_MIN(psf->flac_decoder->output_bytes_remaining, len);
        memcpy(psf->output_buffer + position, psf->flac_decoder->output_ptr, read_len);
        position += read_len;
        bytes_processed += read_len;
        len -= read_len;
        psf->flac_decoder->output_ptr += read_len;
        psf->flac_decoder->output_bytes_remaining -= read_len;
    }

    while (len > 0 && psf->flac_decoder->state == FLAC__DECODER_OK) {
        read_len = SF_MIN(len, 4096); /* Process in chunks of 4096 bytes */
        bytes_processed += read_len;
        len -= read_len;
    }

    if (psf->flac_decoder->state != FLAC__DECODER_OK) {
        psf_log_printf(psf, "FLAC decoder error: %s\n", FLAC__StreamDecoderStateString[psf->flac_decoder->state]);
        psf->frame = NULL;
    }

    return bytes_processed;
}

unsigned process_flac_audio_data(SF_PRIVATE *psf, unsigned len)
{
    unsigned bytes_processed = 0;
    unsigned bytes_remaining = len;

    if (!psf || len == 0)
        return 0;

    if (psf->decoder_state < 0) {
        /* Handle initial error state if present */
        return 0;
    }

    /* Copy any pre-decoded data from the buffer if available */
    if (psf->buffered_data > 0) {
        unsigned copy_len = SF_MIN(bytes_remaining, psf->buffered_data);
        memcpy(psf->output + bytes_processed, psf->decode_buffer, copy_len);
        bytes_processed += copy_len;
        bytes_remaining -= copy_len;
        psf->buffered_data -= copy_len;
        memmove(psf->decode_buffer, psf->decode_buffer + copy_len, psf->buffered_data);
    }

    while (bytes_remaining > 0) {
        if (psf->decoder_state == FLAC__STREAM_DECODER_READ) {
            unsigned read_len = sf_readf_short(psf, (short *)(psf->decode_buffer + psf->buffered_data), bytes_remaining / sizeof(short));
            if (read_len == 0) {
                if (psf->decoder_state == FLAC__STREAM_DECODER_END_OF_STREAM) {
                    /* End of stream reached, no error */
                    break;
                }
                else {
                    /* Log an error if needed */
                    return bytes_processed;
                }
            }
            psf->buffered_data += read_len * sizeof(short);
        }

        if (psf->decoder_state < 0) {
            /* Log error state */
            return bytes_processed;
        }

        unsigned decoded_len = decode_flac_frame(psf, bytes_remaining);
        if (decoded_len == 0) {
            if (psf->decoder_state == FLAC__STREAM_DECODER_END_OF_STREAM) {
                break;
            }
            return bytes_processed;
        }

        bytes_processed += decoded_len;
        bytes_remaining -= decoded_len;
    }

    if (psf->decoder_state < 0 || psf->decoder_state == FLAC__STREAM_DECODER_END_OF_STREAM) {
        /* Nullify frame pointer if needed */
        psf->frame = NULL;
    }

    return bytes_processed;
}
